export class ScanError extends Error {
  constructor(line, column, reason) {
    super(`${line}:${column}: ${reason}`)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

// Longest match first, so `==` is tried before `=`.
const PUNCTUATION = [
  '==', '!=', '<=', '>=', '&&', '||', '->', '=>',
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.',
]

function isLetter(c) {
  return c !== undefined && /^[A-Za-z]$/.test(c)
}

function isDigit(c) {
  return c !== undefined && c >= '0' && c <= '9'
}

function isHexDigit(c) {
  return c !== undefined && /^[0-9a-fA-F]$/.test(c)
}

function isBinDigit(c) {
  return c === '0' || c === '1'
}

function isOctDigit(c) {
  return c !== undefined && c >= '0' && c <= '7'
}

function isIdentStart(c) {
  return isLetter(c) || c === '_'
}

function isIdentPart(c) {
  return isLetter(c) || isDigit(c) || c === '_'
}

