 * Splits `source` into tokens. Each token is
 * `{ kind, text, line, column }`, where `text` is the source text for every
 * kind except `string` and `rawstring`, whose `text` is the decoded value.
 */
export function tokenize(source) {
  const cps = Array.from(source)
  const length = cps.length
  let i = 0
  let line = 1
  let column = 1

  function pos() {
    return { line, column }
  }

  function fail(at, reason) {
    throw new ScanError(at.line, at.column, reason)
  }

  function peek(offset = 0) {
    return cps[i + offset]
  }

  function advance() {
    const c = cps[i++]
    if (c === '\n') {
      line += 1
      column = 1
    } else if (c === '\t') {
      column = (Math.floor((column - 1) / 4) + 1) * 4 + 1
    } else {
      column += 1
    }
    return c
  }

  function requirePeek(startPos, offset = 0) {
    if (i + offset >= length) fail(startPos, 'unterminated string')
    return cps[i + offset]
  }

  function skipBlockComment() {
    const startPos = pos()
    advance()
    advance()
    let depth = 1
    while (depth > 0) {
      if (i >= length) fail(startPos, 'unterminated block comment')
      if (peek() === '/' && peek(1) === '*') {
        advance()
        advance()
        depth += 1
      } else if (peek() === '*' && peek(1) === '/') {
        advance()
        advance()
        depth -= 1
      } else {
        advance()
      }
    }
  }

  function skipTrivia() {
    while (i < length) {
      const c = peek()
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        advance()
      } else if (c === '/' && peek(1) === '/') {
        advance()
        advance()
        while (i < length && peek() !== '\n') advance()
      } else if (c === '/' && peek(1) === '*') {
        skipBlockComment()
      } else {
        return
      }
    }
  }

  function consumeDigitRun(isValidDigit) {
    let text = ''
    if (!isValidDigit(peek())) return text
    text += advance()
    while (true) {
      if (isValidDigit(peek())) {
        text += advance()
      } else if (peek() === '_' && isValidDigit(peek(1))) {
        text += advance()
        text += advance()
      } else {
        break
      }
    }
    return text
  }

  function isWordChar(c) {
    return isLetter(c) || isDigit(c) || c === '_'
  }

  function finishNumber(text, prefixNoDigit, startPos) {
    let trailing = ''
    while (i < length && isWordChar(peek())) {
      trailing += advance()
    }
    if (trailing.length > 0) {
      fail(startPos, `invalid number ${text}${trailing}`)
    }
    if (prefixNoDigit) {
      fail(startPos, `invalid number ${text}`)
    }
    return text
  }

  function scanNumber() {
    const startPos = pos()
    const first = peek()
    const second = peek(1)
    if (first === '0' && (second === 'x' || second === 'X')) {
      let text = advance() + advance()
      const digits = consumeDigitRun(isHexDigit)
      text += digits
      const value = finishNumber(text, digits.length === 0, startPos)
      return { kind: 'number', text: value, ...startPos }
    }
    if (first === '0' && (second === 'b' || second === 'B')) {
      let text = advance() + advance()
      const digits = consumeDigitRun(isBinDigit)
      text += digits
      const value = finishNumber(text, digits.length === 0, startPos)
      return { kind: 'number', text: value, ...startPos }
    }
    if (first === '0' && (second === 'o' || second === 'O')) {
      let text = advance() + advance()
      const digits = consumeDigitRun(isOctDigit)
      text += digits
      const value = finishNumber(text, digits.length === 0, startPos)
      return { kind: 'number', text: value, ...startPos }
    }

    let text = consumeDigitRun(isDigit)
    if (peek() === '.' && isDigit(peek(1))) {
      text += advance()
      text += consumeDigitRun(isDigit)
    }
    if (peek() === 'e' || peek() === 'E') {
      const hasSign = peek(1) === '+' || peek(1) === '-'
      const digitOffset = hasSign ? 2 : 1
      if (isDigit(peek(digitOffset))) {
        text += advance()
        if (hasSign) text += advance()
        text += consumeDigitRun(isDigit)
      }
    }
    const value = finishNumber(text, false, startPos)
    return { kind: 'number', text: value, ...startPos }
  }

