    const ec = requirePeek(startPos)
    switch (ec) {
      case 'n':
        advance()
        return '\n'
      case 't':
        advance()
        return '\t'
      case 'r':
        advance()
        return '\r'
      case '\\':
        advance()
        return '\\'
      case '"':
        advance()
        return '"'
      case '0':
        advance()
        return '\0'
      case 'x': {
        advance()
        const h1 = requirePeek(startPos)
        if (!isHexDigit(h1)) fail(backslashPos, 'invalid escape \\x')
        const h2 = requirePeek(startPos, 1)
        if (!isHexDigit(h2)) fail(backslashPos, 'invalid escape \\x')
        advance()
        advance()
        return String.fromCodePoint(parseInt(h1 + h2, 16))
      }
      case 'u': {
        advance()
        const brace = requirePeek(startPos)
        if (brace !== '{') fail(backslashPos, 'invalid escape \\u')
        advance()
        let hex = ''
        while (true) {
          const c2 = requirePeek(startPos)
          if (c2 === '}') break
          if (!isHexDigit(c2)) fail(backslashPos, 'invalid escape \\u')
          hex += c2
          advance()
        }
        if (hex.length === 0) fail(backslashPos, 'invalid escape \\u')
        advance()
        const code = parseInt(hex, 16)
        if (code > 0x10ffff) fail(backslashPos, 'invalid escape \\u')
        return String.fromCodePoint(code)
      }
      default:
        fail(backslashPos, `invalid escape \\${ec}`)
    }
  }

  function scanString() {
    const startPos = pos()
    advance()
    let value = ''
    while (true) {
      if (i >= length) fail(startPos, 'unterminated string')
      const charPos = pos()
      const c = peek()
      if (c === '"') {
        advance()
        return { kind: 'string', text: value, ...startPos }
      }
      if (c === '\n') {
        fail(charPos, 'newline in string')
      }
      if (c === '\\') {
        advance()
        value += decodeEscape(startPos, charPos)
      } else {
        advance()
        value += c
      }
    }
  }

  function scanRawString() {
    const startPos = pos()
    advance()
    advance()
    let value = ''
    while (true) {
      if (i >= length) fail(startPos, 'unterminated string')
      const c = advance()
      if (c === '"') {
        return { kind: 'rawstring', text: value, ...startPos }
      }
      value += c
    }
  }

  function scanIdentifier() {
    const startPos = pos()
    let text = advance()
    while (i < length && isIdentPart(peek())) {
      text += advance()
    }
    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
    return { kind, text, ...startPos }
  }

  function scanPunctuation() {
    const startPos = pos()
    for (const p of PUNCTUATION) {
      let matches = true
      for (let k = 0; k < p.length; k += 1) {
        if (peek(k) !== p[k]) {
          matches = false
          break
        }
