    const c = advance()
    fail(startPos, `unexpected character ${c}`)
  }

  const tokens = []
  while (true) {
    skipTrivia()
    if (i >= length) break
    const c = peek()
    if (c === '"') {
      tokens.push(scanString())
    } else if (c === 'r' && peek(1) === '"') {
      tokens.push(scanRawString())
    } else if (isIdentStart(c)) {
      tokens.push(scanIdentifier())
    } else if (isDigit(c)) {
      tokens.push(scanNumber())
    } else {
      tokens.push(scanPunctuation())
    }
  }
  return tokens
