 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { readFileSync } from 'node:fs'
import { tokenize, ScanError } from './lexer.js'

const STAT_KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function usageError() {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    usageError()
    return
  }
  const mode = args[0]
  const source = readFileSync(0, 'utf8')

  let tokens
  try {
    tokens = tokenize(source)
  } catch (err) {
    if (err instanceof ScanError) {
      process.stderr.write(`error: ${err.line}:${err.column}: ${err.reason}\n`)
      process.exit(2)
      return
    }
    throw err
  }

  let output
  if (mode === 'tokens') {
    output = tokens
      .map((t) => {
        const body = t.kind === 'string' || t.kind === 'rawstring' ? JSON.stringify(t.text) : t.text
        return `${t.line}:${t.column} ${t.kind} ${body}\n`
      })
      .join('')
  } else {
    const counts = Object.fromEntries(STAT_KINDS.map((k) => [k, 0]))
    for (const t of tokens) counts[t.kind] += 1
    output = STAT_KINDS.map((k) => `${k} ${counts[k]}\n`).join('') + `total ${tokens.length}\n`
  }

  process.stdout.write(output)
  process.exit(0)
}

main()
